() => {
  const widget = document.querySelector('.bg-gray-50') || document.querySelector('[class*="widget"]');
  // Look for inputs in the inference widget
  const inputs = Array.from(document.querySelectorAll('input[placeholder*="sentence"]'));
  return {
    inputCount: inputs.length,
    placeholders: inputs.map(i => i.placeholder),
    values: inputs.map(i => i.value),
    parents: inputs.map(i => i.closest('label')?.textContent?.trim() || i.parentElement?.textContent?.trim()?.substring(0, 100))
  };
}

async () => {
  const response = await fetch('https://api-inference.huggingface.co/models/sentence-transformers/all-MiniLM-L6-v2', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({
      inputs: {
        source_sentence: 'Tomorrow is Sunday',
        sentences: ['Eat a burger on Sunday']
      }
    })
  });
  const text = await response.text();
  return {status: response.status, body: text};
}

