() => {
  const iframes = document.querySelectorAll('iframe');
  return Array.from(iframes).map(f => ({src: f.src, id: f.id, name: f.name}));
}

() => {
  const iframes = document.querySelectorAll('iframe');
  document.title = 'IFRAMES:' + iframes.length + '|titled';
}

() => {
  // Try to close any modal/overlay
  const overlay = document.querySelector('[role="dialog"]') || document.querySelector('.modal') || document.querySelector('[class*="overlay"]');
  if (overlay) overlay.remove();
  // Also try to remove any backdrop
  document.querySelectorAll('[class*="backdrop"]').forEach(b => b.remove());
  return 'overlay removal attempted';
}

async () => {
  try {
    const r = await fetch('https://api-inference.huggingface.co/models/sentence-transformers/all-MiniLM-L6-v2', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({inputs: {source_sentence: 'Tomorrow is Sunday', sentences: ['Eat a burger on Sunday']}})
    });
    const text = await r.text();
    const div = document.createElement('div');
    div.id = 'api_result';
    div.style.display = 'none';
    div.textContent = 'STATUS:' + r.status + ' BODY:' + text;
    document.body.appendChild(div);
    return 'wrote div';
  } catch (e) {
    const div = document.createElement('div');
    div.id = 'api_error';
    div.style.display = 'none';
    div.textContent = 'ERROR:' + e.message;
    document.body.appendChild(div);
    return 'wrote error div';
  }
}

() => {
  const r = document.getElementById('api_result');
  const e = document.getElementById('api_error');
  return (r ? r.textContent : 'NO_RESULT') + '||' + (e ? e.textContent : 'NO_ERROR');
}

() => {
  let r = document.getElementById('api_result');
  let e = document.getElementById('api_error');
  if (!r && !e) {
    const div = document.createElement('div');
    div.id = 'api_status';
    div.style.cssText = 'position:fixed;top:0;left:0;background:yellow;color:black;z-index:99999;padding:20px;font-size:24px;border:3px solid red;';
    div.textContent = 'NO RESULT YET - check after fetch';
    document.body.appendChild(div);
  } else {
    const div = document.createElement('div');
    div.id = 'api_status';
    div.style.cssText = 'position:fixed;top:0;left:0;background:yellow;color:black;z-index:99999;padding:20px;font-size:14px;border:3px solid red;word-break:break-all;';
    div.textContent = 'R:' + (r?r.textContent:'none') + ' | E:' + (e?e.textContent:'none');
    document.body.appendChild(div);
  }
  return 'done';
}

() => {
  // Remove any visible overlay modals
  document.querySelectorAll('*').forEach(el => {
    const style = window.getComputedStyle(el);
    if (style.position === 'fixed' && parseInt(style.zIndex || 0) > 0 && el.querySelector('a[href*="login"]')) {
      el.remove();
    }
  });
  // Also reset body styles
  document.body.style.overflow = 'auto';
  document.body.style.paddingRight = '0';
  document.documentElement.style.overflow = 'auto';
  return 'attempted cleanup';
}

