() => {
  // Send Escape to dismiss any modal
  document.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape', bubbles: true}));
  document.dispatchEvent(new KeyboardEvent('keyup', {key: 'Escape', bubbles: true}));
  // Try to remove the modal/overlay
  const elems = document.querySelectorAll('*');
  let removed = 0;
  for (const el of elems) {
    try {
      if (el.textContent && el.textContent.includes('Please login with your Hugging Face account') && el.children.length < 10) {
        el.remove();
        removed++;
      }
    } catch(e) {}
  }
  return 'removed: ' + removed;
}

() => {
  return fetch('https://api-inference.huggingface.co/models/sentence-transformers/all-MiniLM-L6-v2', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({inputs: {source_sentence: 'Tomorrow is Sunday', sentences: ['Eat a burger on Sunday']}})
  }).then(r => r.text()).then(t => ({ok: true, t: t.substring(0, 1000)}));
}

() => {
  const xhr = new XMLHttpRequest();
  xhr.open('POST', 'https://api-inference.huggingface.co/models/sentence-transformers/all-MiniLM-L6-v2', false);
  xhr.setRequestHeader('Content-Type', 'application/json');
  xhr.send(JSON.stringify({inputs: {source_sentence: 'Tomorrow is Sunday', sentences: ['Eat a burger on Sunday']}}));
  return {status: xhr.status, text: xhr.responseText};
}

() => {
  // Look for HF tokens in window object
  const out = {};
  try { out.hf_token = window.HF_TOKEN; } catch(e){}
  try { out.huggingface = window.huggingface; } catch(e){}
  try { out.env = window.env; } catch(e){}
  // Look for any meta tags with API info
  const metas = Array.from(document.querySelectorAll('meta'));
  out.meta_names = metas.map(m => m.name || m.getAttribute('property')).filter(n => n).slice(0, 30);
  // Look for script tags with api
  const scripts = Array.from(document.querySelectorAll('script[src]'));
  out.scripts = scripts.map(s => s.src).filter(s => s.includes('api') || s.includes('inference')).slice(0, 10);
  return out;
}

